#include <bits/stdc++.h>
using namespace std;
int W,H;
bool grid[105][105];
vector<array<int,3>> groups;
long long solve(vector<int>& remaining){
    int fr=-1,fc=-1;
    for(int r=0;r<H && fr<0;r++)
        for(int c=0;c<W;c++)
            if(!grid[r][c]){ fr=r; fc=c; break; }
    if(fr<0) return 1;
    long long total=0;
    for(size_t g=0; g<groups.size(); g++){
        if(remaining[g]<=0) continue;
        int tw=groups[g][1], th=groups[g][2];
        if(fc+tw<=W && fr+th<=H){
            bool ok=true;
            for(int rr=fr; rr<fr+th && ok; rr++)
                for(int cc=fc; cc<fc+tw; cc++)
                    if(grid[rr][cc]){ ok=false; break; }
            if(ok){
                for(int rr=fr; rr<fr+th; rr++) for(int cc=fc; cc<fc+tw; cc++) grid[rr][cc]=true;
                remaining[g]--;
                total += solve(remaining);
                remaining[g]++;
                for(int rr=fr; rr<fr+th; rr++) for(int cc=fc; cc<fc+tw; cc++) grid[rr][cc]=false;
            }
        }
    }
    return total;
}
int main(){
    int w,h,n;
    while(cin>>w>>h>>n){
        W=w;H=h;
        groups.clear();
        vector<int> remaining(n);
        for(int i=0;i<n;i++){
            int m,tw,th; cin>>m>>tw>>th;
            groups.push_back({m,tw,th});
            remaining[i]=m;
        }
        memset(grid,0,sizeof(grid));
        cout << solve(remaining) << "\n";
    }
}

